 */

const NAME_RE = /^[A-Za-z0-9_.-]+$/
const COST_RE = /^[0-9]+$/

/** A directive on a specific line has the wrong shape or content. */
export class LineError extends Error {
  constructor(line, message) {
    super(message)
    this.line = line
  }
}

/** A `dep` line names a task no `task` line ever declares. */
export class UnknownTaskError extends Error {
  constructor(name) {
    super(name)
    this.name_ = name
  }
}

/**
 * Parses `input` into a graph: a map of task name to cost, and a map of
 * task name to the set of names it depends on. Throws `LineError` for a
 * malformed line and `UnknownTaskError` for a `dep` line that names an
 * undeclared task.
 */
export function parseGraph(input) {
  const rawLines = input.split('\n')
  if (rawLines.length > 0 && rawLines[rawLines.length - 1] === '') rawLines.pop()

  const tasks = new Map()
  const deps = new Map()
  const depRefs = []

  rawLines.forEach((line, index) => {
    const lineNo = index + 1
    const trimmed = line.trim()
    if (trimmed === '' || trimmed.startsWith('#')) return

    const parts = trimmed.split(/\s+/)
    const directive = parts[0]

    if (directive === 'task') {
      if (parts.length !== 3) throw new LineError(lineNo, 'expected task <name> <cost>')
      const [, name, costText] = parts
      if (!NAME_RE.test(name)) throw new LineError(lineNo, `invalid task name ${name}`)
      if (!COST_RE.test(costText)) throw new LineError(lineNo, 'cost must be a non-negative integer')
      if (tasks.has(name)) throw new LineError(lineNo, `task ${name} is declared twice`)
      tasks.set(name, parseInt(costText, 10))
      if (!deps.has(name)) deps.set(name, new Set())
    } else if (directive === 'dep') {
      if (parts.length < 3) throw new LineError(lineNo, 'expected dep <name> <dependency>...')
      const name = parts[1]
      const dependencies = parts.slice(2)
      for (const each of [name, ...dependencies]) {
        if (!NAME_RE.test(each)) throw new LineError(lineNo, `invalid task name ${each}`)
      }
      depRefs.push(name, ...dependencies)
      if (!deps.has(name)) deps.set(name, new Set())
      const set = deps.get(name)
      for (const dependency of dependencies) set.add(dependency)
    } else {
      throw new LineError(lineNo, `unknown directive ${directive}`)
    }
  })

  for (const name of depRefs) {
    if (!tasks.has(name)) throw new UnknownTaskError(name)
  }

  return { tasks, deps }
}
