 * Scheduling computations over a parsed build graph: dependency cycles,
 * unlimited-worker timings and waves, and finite-worker packing.
 */

/**
 * Depth-first search for the first cycle, visiting tasks and their
 * dependencies in ascending name order. Returns the cycle as an array of
 * names starting and ending with the re-entered task, or `null` when the
 * graph is acyclic.
 */
export function findCycle(tasks, deps) {
  const names = [...tasks.keys()].sort()
  const state = new Map()
  const stack = []

  function visit(node) {
    state.set(node, 'visiting')
    stack.push(node)
    const dependencies = [...(deps.get(node) || [])].sort()
    for (const dependency of dependencies) {
      const dependencyState = state.get(dependency)
      if (dependencyState === 'visiting') {
        const start = stack.indexOf(dependency)
        return stack.slice(start).concat(dependency)
      }
      if (dependencyState === undefined) {
        const found = visit(dependency)
        if (found) return found
      }
    }
    stack.pop()
    state.set(node, 'done')
    return null
  }

  for (const name of names) {
    if (!state.has(name)) {
      const found = visit(name)
      if (found) return found
    }
  }
  return null
}

/**
 * Computes, for every task, its start, finish and wave depth under
 * unlimited workers. Start is the greatest finish of its dependencies (0
 * when it has none); finish is start plus cost; depth is one more than the
 * greatest depth of its dependencies (0 when it has none).
 */
export function computeTimings(tasks, deps) {
  const finishMemo = new Map()
  const depthMemo = new Map()

  function finish(name) {
    if (finishMemo.has(name)) return finishMemo.get(name)
    const dependencies = deps.get(name) || new Set()
    let start = 0
    for (const dependency of dependencies) start = Math.max(start, finish(dependency))
    const result = start + tasks.get(name)
    finishMemo.set(name, result)
    return result
  }

  function depth(name) {
    if (depthMemo.has(name)) return depthMemo.get(name)
    const dependencies = deps.get(name) || new Set()
    let result = 0
    for (const dependency of dependencies) result = Math.max(result, depth(dependency) + 1)
    depthMemo.set(name, result)
    return result
  }

  const info = new Map()
  for (const name of tasks.keys()) {
    const cost = tasks.get(name)
    const finishTime = finish(name)
    info.set(name, { start: finishTime - cost, finish: finishTime, depth: depth(name) })
  }
  return info
}

/**
 * Computes each task's packing priority: the cost of the longest chain of
 * costs starting at it and continuing through its dependents down to a
 * task nothing depends on.
 */
function computePriorities(tasks, deps) {
  const dependents = new Map()
  for (const name of tasks.keys()) dependents.set(name, [])
  for (const [name, dependencies] of deps) {
    for (const dependency of dependencies) {
      if (!dependents.has(dependency)) dependents.set(dependency, [])
      dependents.get(dependency).push(name)
    }
  }

  const memo = new Map()
  function priority(name) {
    if (memo.has(name)) return memo.get(name)
    let best = 0
    for (const dependent of dependents.get(name) || []) best = Math.max(best, priority(dependent))
    const result = tasks.get(name) + best
    memo.set(name, result)
    return result
  }

  const result = new Map()
  for (const name of tasks.keys()) result.set(name, priority(name))
  return result
}

/**
 * Simulates the graph on `workerCount` workers using greatest-priority,
 * ascending-name-tiebreak, smallest-free-worker-index list scheduling.
 * Returns one array of `{ name, start, finish }` runs per worker, in the
 * order each worker ran them.
 */
export function pack(tasks, deps, workerCount) {
  const priorities = computePriorities(tasks, deps)
  const finishTime = new Map()
  const remaining = new Set(tasks.keys())
  const workers = Array.from({ length: workerCount }, () => ({ available: 0, runs: [] }))

  let time = 0
  while (remaining.size > 0) {
    for (;;) {
      const freeIndex = workers.findIndex((worker) => worker.available <= time)
      if (freeIndex === -1) break

      let chosen = null
      for (const name of remaining) {
        const dependencies = deps.get(name) || new Set()
        const ready = [...dependencies].every((dependency) => finishTime.get(dependency) <= time)
        if (!ready) continue
        if (
          chosen === null ||
          priorities.get(name) > priorities.get(chosen) ||
          (priorities.get(name) === priorities.get(chosen) && name < chosen)
        ) {
          chosen = name
        }
      }
      if (chosen === null) break

      const start = time
      const finish = start + tasks.get(chosen)
      workers[freeIndex].runs.push({ name: chosen, start, finish })
      workers[freeIndex].available = finish
      finishTime.set(chosen, finish)
      remaining.delete(chosen)
    }

    if (remaining.size === 0) break
    let next = Infinity
    for (const worker of workers) {
      if (worker.available > time) next = Math.min(next, worker.available)
    }
    time = next
  }

  return workers
}
