/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */

import { readFileSync } from 'node:fs'
import { LineError, UnknownTaskError, parseGraph } from './parse.js'
import { computeTimings, findCycle, pack } from './schedule.js'

const USAGE = 'error: usage: cli.js waves|explain|pack <workers>'
const WORKERS_RE = /^[1-9][0-9]*$/

function fail(message) {
  process.stderr.write(`${message}\n`)
  process.exitCode = 2
  return null
}

function parseArgs(argv) {
  if (argv.length === 1 && (argv[0] === 'waves' || argv[0] === 'explain')) {
    return { mode: argv[0] }
  }
  if (argv.length === 2 && argv[0] === 'pack') {
    if (!WORKERS_RE.test(argv[1])) {
      fail('error: workers must be a positive integer')
      return null
    }
    return { mode: 'pack', workers: parseInt(argv[1], 10) }
  }
  fail(USAGE)
  return null
}

function main() {
  const args = parseArgs(process.argv.slice(2))
  if (args === null) return

  const input = readFileSync(0, 'utf8')

  let graph
  try {
    graph = parseGraph(input)
  } catch (error) {
    if (error instanceof LineError) {
      fail(`error: line ${error.line}: ${error.message}`)
    } else if (error instanceof UnknownTaskError) {
      fail(`error: unknown task ${error.name_}`)
    } else {
      throw error
    }
    return
  }

  const { tasks, deps } = graph

  const cycle = findCycle(tasks, deps)
  if (cycle) {
    process.stderr.write(`error: cycle: ${cycle.join(' -> ')}\n`)
    process.exitCode = 3
    return
  }

  if (args.mode === 'waves') {
    printWaves(tasks, deps)
  } else if (args.mode === 'explain') {
    printExplain(tasks, deps)
  } else {
    printPack(tasks, deps, args.workers)
  }
}

function printWaves(tasks, deps) {
  const info = computeTimings(tasks, deps)
  const names = [...tasks.keys()].sort()
  const waves = []
  for (const name of names) {
    const depth = info.get(name).depth
    if (!waves[depth]) waves[depth] = []
    waves[depth].push(name)
  }

  const lines = []
  for (let k = 0; k < waves.length; k += 1) {
    lines.push(`wave ${k}: ${waves[k].join(' ')}`)
  }
  const total = names.length === 0 ? 0 : Math.max(...names.map((name) => info.get(name).finish))
  lines.push(`total ${total}`)
  process.stdout.write(lines.map((line) => `${line}\n`).join(''))
}

function printExplain(tasks, deps) {
  const info = computeTimings(tasks, deps)
  const names = [...tasks.keys()].sort()
  const lines = names.map((name) => {
    const { start, finish, depth } = info.get(name)
    return `${name} start=${start} finish=${finish} depth=${depth}`
  })
  const total = names.length === 0 ? 0 : Math.max(...names.map((name) => info.get(name).finish))
  lines.push(`total ${total}`)
  process.stdout.write(lines.map((line) => `${line}\n`).join(''))
}

function printPack(tasks, deps, workerCount) {
  const workers = pack(tasks, deps, workerCount)
  const lines = workers.map((worker, index) => {
    const runs = worker.runs.map((run) => ` ${run.name}@${run.start}-${run.finish}`).join('')
    return `worker ${index}:${runs}`
  })
  const makespan = workers.reduce((max, worker) => {
    return worker.runs.reduce((m, run) => Math.max(m, run.finish), max)
  }, 0)
  lines.push(`makespan ${makespan}`)
  process.stdout.write(lines.map((line) => `${line}\n`).join(''))
}

main()
"}

